{"name":"typec_unregister_partner","qualified_name":"workspace-linux.drivers.usb.typec.class.typec_unregister_partner","label":"Function","file_path":"/workspace/linux/drivers/usb/typec/class.c","start_line":1174,"end_line":1195,"source":"void typec_unregister_partner(struct typec_partner *partner)
{
	struct typec_port *port;

	if (IS_ERR_OR_NULL(partner))
		return;

	port = to_typec_port(partner->dev.parent);

	mutex_lock(&port->partner_link_lock);
	if (port->usb2_dev) {
		typec_partner_unlink_device(partner, port->usb2_dev);
		port->usb2_dev = NULL;
	}
	if (port->usb3_dev) {
		typec_partner_unlink_device(partner, port->usb3_dev);
		port->usb3_dev = NULL;
	}

	device_unregister(&partner->dev);
	mutex_unlock(&port->partner_link_lock);
}
