{"name":"ucsi_check_connection","qualified_name":"workspace-linux.drivers.usb.typec.ucsi.ucsi.ucsi_check_connection","label":"Function","file_path":"/workspace/linux/drivers/usb/typec/ucsi/ucsi.c","start_line":1201,"end_line":1225,"source":"static int ucsi_check_connection(struct ucsi_connector *con)
{
	u8 prev_state = UCSI_CONSTAT(con, CONNECTED);
	int ret;

	ret = ucsi_get_connector_status(con, false);
	if (ret) {
		dev_err(con->ucsi->dev, "GET_CONNECTOR_STATUS failed (%d)\n", ret);
		return ret;
	}

	if (UCSI_CONSTAT(con, CONNECTED)) {
		if (prev_state)
			return 0;
		ucsi_register_partner(con);
		ucsi_pwr_opmode_change(con);
		ucsi_partner_change(con);
	} else {
		ucsi_partner_change(con);
		ucsi_port_psy_changed(con);
		ucsi_unregister_partner(con);
	}

	return 0;
}
